{ "hypotheses": [
  {
    "root_cause": "Internal application fault in feature-service",
    "mechanism": "The feature-service process is throwing unhandled exceptions, exhausting request-handling resources, or hitting a bad code path, causing a substantial fraction of requests to return 5xx.",
    "statement": "The fault originates inside service:gridcast:feature-service itself."
  },
  {
    "root_cause": "Postgres database degradation",
    "mechanism": "Postgres is experiencing slow queries, connection saturation, lock contention, or a brief availability drop, causing feature-service database calls to fail or time out and surface as 5xx responses.",
    "statement": "The fault originates in service:gridcast:postgres and cascades into feature-service."
  },
  {
    "root_cause": "Upstream traffic overload from forecast-pipeline",
    "mechanism": "forecast-pipeline issued a sudden burst of expensive, malformed, or otherwise harmful requests to feature-service, exhausting its capacity and forcing 5xx errors.",
    "statement": "The fault originates in service:gridcast:forecast-pipeline, the consumer of feature-service."
  },
  {
    "root_cause": "Bad feature-service rollout or capacity loss",
    "mechanism": "A rolling deployment or replica change during the incident left feature-service with insufficient ready pods or misconfigured pods, so available replicas could not handle traffic and returned 5xx.",
    "statement": "The fault originates in k8s:gridcast:deployment:feature-service due to a deployment or scaling problem."
  },
  {
    "root_cause": "Kubernetes Service routing/selector misconfiguration",
    "mechanism": "The feature-service Kubernetes Service began routing traffic to unready or mismatched pods, causing requests to fail with 5xx.",
    "statement": "The fault originates in k8s:gridcast:service:feature-service due to incorrect routing."
  }
]}
